head.script:
scwin.trigger1_onclick = function(e) {
    WebSquare.wUnit.getObjById('calendar1').disableBeforeDate("20180110");
};
scwin.trigger2_onclick = function(e) {
    WebSquare.wUnit.getObjById('calendar1').disableAfterDate("20180120");
};
scwin.trigger3_onclick = function(e) {
    WebSquare.wUnit.getObjById('calendar1').enableAllDate();
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_selectbox_month_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_selectbox_month_itemTable_0').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //for mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('calendar1').gotoYear(2018)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('calendar1').gotoMonth(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_cell_2_5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/19'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_cell_3_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/19'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'disableBeforeDate'버튼을 클릭한다.
    //2. Click the 'disableBeforeDate' button.
    //Verify step 2. The date before January 10, 2018 (9th) is disabled.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_cell_1_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/10'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_cell_1_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/10'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 'enableAllDate'버튼을 클릭한다.
    //3. Click the 'enableAllDate' button.
    //Verify step 3. All dates are enabled (10 to 20 days are enabled.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('calendar1_cell_1_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/09'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('calendar1_cell_3_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('calendar1_currentDate').textContent == '2018/01/21'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
